head.script:
scwin.gVar = {
    "cID" : ""
}



scwin.onpageload = function () {
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제 (커스텀 id 가능 -> scwin.target1 레퍼런스로 제거)
    if (typeof scwin.target1 !== 'undefined' && scwin.target1) {
        scwin.target1.remove();
    }

    // 조건 설정
    let cID = scwin.gVar["cID"];

    // getID 는 id 설정 유무에 따른 반환값 확인이 목적이므로 windowContainer 를 직접 생성
    //  - cID 가 빈값이면 dynamicCreate 가 내부 규칙으로 임의 id 자동 부여 (createBasicWindowContainer 는 빈값 시 target1 로 고정되어 부적합)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    let strTarget = '';
    strTarget += '<w2:windowContainer ' + strNameSpace + ' style="width:500px; height:300px; position:relative;">';
    strTarget += '<w2:windowToolbar>';
    strTarget += '<w2:controlIconLayer>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '<w2:controlIcon></w2:controlIcon>';
    strTarget += '</w2:controlIconLayer>';
    strTarget += '<w2:nameLayer></w2:nameLayer>';
    strTarget += '<w2:selectedNameLayer></w2:selectedNameLayer>';
    strTarget += '</w2:windowToolbar>';
    strTarget += '</w2:windowContainer>';

    // base(common_M)가 objParent.scwin.target1 로 접근하므로 scwin.target1 에 생성된 windowContainer 를 설정 (빈 cID -> 자동 id)
    scwin.target1 = await $p.dynamicCreate(cID, "windowContainer", strTarget, grp_comp);

    // 내용 확인용 윈도우 생성
    scwin.target1.createWindow({
        title : "windowContainer_link_1",
        src : "/sample/common_link/windowContainer_link_1.xml",
        windowTitle : "TEST",
        windowId : "test001",
        openAction : "selectWindow"
    });
}
